import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parse } from "yaml";
import { ROOT, fail } from "./common.mjs";

const SOURCE = join(ROOT, "desktop", "src", "features", "knowledge", "ontology.yml");
const TARGET = join(ROOT, "angular", "app", "features", "novel", "novel.knowledge.ontology.data.ts");
const SEVERITIES = ["error", "warning"];

const HEADER = [
  "// generated by _scripts/ontology.mjs from desktop/src/features/knowledge/ontology.yml, do not edit",
  'import { LanguageKey } from "@app/core/language/language.models";',
];

function normalize(text) {
  return text.replace(/\r\n/g, "\n");
}

function text(value) {
  return JSON.stringify(value);
}

function list(values) {
  return `[${values.map(text).join(", ")}]`;
}

function union(values) {
  return values.map(text).join(" | ");
}

function entries(section, name) {
  if (section === null || typeof section !== "object" || Array.isArray(section)) throw new Error(`${name} must be a map`);
  return Object.entries(section).map(([key, def]) => [key, def ?? {}]);
}

function loadOntology(source) {
  const document = parse(source);
  if (!Number.isInteger(document?.version)) throw new Error("version must be an integer");
  const types = entries(document.entity_types, "entity_types");
  const scalars = entries(document.scalars, "scalars");
  const relationships = entries(document.relationships, "relationships");
  const rules = entries(document.rules, "rules");
  return { version: document.version, types, scalars, relationships, rules };
}

function checkTypes(names, def, where) {
  for (const name of [...(def.domain ?? []), ...(def.range ?? [])]) {
    if (!names.includes(name)) throw new Error(`${where} uses the undeclared type ${name}`);
  }
}

function validate(ontology) {
  const names = ontology.types.map(([key]) => key);
  const predicates = [...ontology.scalars, ...ontology.relationships];
  if (names.length === 0 || ontology.rules.length === 0) throw new Error("entity_types and rules must not be empty");
  if (new Set(predicates.map(([key]) => key)).size !== predicates.length) throw new Error("a predicate is declared twice");
  for (const [key, def] of predicates) checkTypes(names, def, key);
  for (const [key, def] of ontology.rules) {
    if (!SEVERITIES.includes(def.severity)) throw new Error(`rule ${key} has an invalid severity`);
  }
}

function typeRow([key, def]) {
  const properties = list(def.properties ?? []);
  const abstract = def.abstract === true;
  return `  { key: ${text(key)}, abstract: ${abstract}, properties: ${properties}, labelKey: ${text(`novel.knowledge.type.${key}`)}, hintKey: ${text(`novel.knowledge.type.${key}.hint`)} },`;
}

function predicateRow(kind, [key, def]) {
  const limit = kind === "scalar" ? def.single === true : def.unique_range === true;
  const range = list(kind === "scalar" ? [] : def.range ?? []);
  return `  { key: ${text(key)}, kind: ${text(kind)}, labelKey: ${text(`novel.knowledge.pred.${key}`)}, domain: ${list(def.domain ?? [])}, range: ${range}, limit: ${limit} },`;
}

function ruleRow([key, def]) {
  return `  { id: ${text(key)}, severity: ${text(def.severity)}, labelKey: ${text(`novel.knowledge.rule.${key}`)}, descKey: ${text(`novel.knowledge.rule.${key}.desc`)} },`;
}

function render(ontology, source) {
  const typeNames = ontology.types.map(([key]) => key);
  const ruleIds = ontology.rules.map(([key]) => key);
  const lines = [...HEADER, ""];
  lines.push(`export const ONTOLOGY_VERSION: number = ${ontology.version};`);
  lines.push(`export const ONTOLOGY_YAML: string = ${text(source)};`, "");
  lines.push(`export type EntityType = ${union(typeNames)};`);
  lines.push(`export type PredicateKind = ${union(["scalar", "relationship"])};`);
  lines.push(`export type RuleId = ${union(ruleIds)};`, "");
  lines.push("export interface TypeData {", "  key: EntityType;", "  abstract: boolean;", "  properties: string[];", "  labelKey: LanguageKey;", "  hintKey: LanguageKey;", "}", "");
  lines.push("export interface PredicateData {", "  key: string;", "  kind: PredicateKind;", "  labelKey: LanguageKey;", "  domain: EntityType[];", "  range: EntityType[];", "  limit: boolean;", "}", "");
  lines.push("export interface RuleData {", "  id: RuleId;", `  severity: ${union(SEVERITIES)};`, "  labelKey: LanguageKey;", "  descKey: LanguageKey;", "}", "");
  lines.push("export const TYPE_DATA: TypeData[] = [", ...ontology.types.map(typeRow), "];", "");
  lines.push("export const PREDICATE_DATA: PredicateData[] = [");
  lines.push(...ontology.scalars.map((entry) => predicateRow("scalar", entry)));
  lines.push(...ontology.relationships.map((entry) => predicateRow("relationship", entry)), "];", "");
  lines.push("export const RULE_DATA: RuleData[] = [", ...ontology.rules.map(ruleRow), "];", "");
  return lines.join("\n");
}

function generate() {
  const source = normalize(readFileSync(SOURCE, "utf8"));
  const ontology = loadOntology(source);
  validate(ontology);
  return render(ontology, source);
}

function main() {
  const output = generate();
  if (process.argv.includes("--check")) {
    const current = existsSync(TARGET) ? normalize(readFileSync(TARGET, "utf8")) : null;
    if (current !== output) throw new Error("novel.knowledge.ontology.data.ts is out of date, run `pnpm ontology`");
    console.log("ontology data is up to date");
    return;
  }
  writeFileSync(TARGET, output);
  console.log(`ontology data written: ${TARGET}`);
}

try {
  main();
} catch (error) {
  fail(error);
}
